package com.mangabridge.bootstrap.work;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.mangabridge.bootstrap.MangabridgeApplication;
import com.mangabridge.bootstrap.auth.AuthModels.Role;
import com.mangabridge.bootstrap.auth.TrackingAuthDao;
import com.mangabridge.bootstrap.config.RequiredEnvironment;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.*;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.context.annotation.*;
import org.springframework.dao.DataAccessResourceFailureException;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.test.context.*;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
@SpringBootTest(classes=MangabridgeApplication.class,webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@ContextConfiguration(initializers=RequiredEnvironment.class)
@ActiveProfiles("local")
@Import(RecommendIntegrationTest.Fixtures.class)
class RecommendIntegrationTest {
 @Autowired TestRestTemplate http;@Autowired JdbcTemplate jdbc;@Autowired TrackingAuthDao tracking;
 @MockitoSpyBean java.time.Clock clock; @MockitoSpyBean RecommendDao recommendations; @MockitoSpyBean WorkDao dao;@MockitoSpyBean ViewDao views;
 @org.springframework.boot.test.web.server.LocalServerPort int port;
 final Map<Role,Identity> users=new EnumMap<>(Role.class);final Set<String> works=new HashSet<>(),episodes=new HashSet<>();
 record Identity(long id,String token) { }
 @TestConfiguration static class Fixtures {@Bean @Primary TrackingAuthDao workTrackingAuthDao(JdbcTemplate jdbc){return new TrackingAuthDao(jdbc);}}
 @BeforeEach void setup(){for(Role role:Role.values()){var key=new GeneratedKeyHolder();jdbc.update(c->{var ps=c.prepareStatement("INSERT INTO demo_account(login_id,display_name,role,password_hash) VALUES (?,?,?,?)",Statement.RETURN_GENERATED_KEYS);ps.setString(1,"test.work."+UUID.randomUUID());ps.setString(2,"work fixture");ps.setString(3,role.name());ps.setString(4,"unused-test-hash");return ps;},key);long id=key.getKey().longValue();byte[] bytes=new byte[32];new java.security.SecureRandom().nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);users.put(role,new Identity(id,token));jdbc.update("INSERT INTO auth_token(token_hash,account_id,expires_at) VALUES (?,?,?)",digest(token),id,Timestamp.from(Instant.now().plusSeconds(3600)));}}
 static byte[] digest(String token){try{return java.security.MessageDigest.getInstance("SHA-256").digest(token.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){throw new AssertionError(e);}}
 @AfterEach void cleanup(){reset(dao,views,clock,recommendations);tracking.cleanupAudits();for(String id:episodes){jdbc.update("DELETE FROM work_episode WHERE episode_id=?",id);jdbc.update("DELETE FROM episode_view_daily WHERE episode_id=?",id);jdbc.update("DELETE FROM episode_view_count WHERE episode_id=?",id);jdbc.update("UPDATE episode SET published_translation_version_id=NULL WHERE id=?",id);jdbc.update("DELETE FROM publication WHERE episode_id=?",id);jdbc.update("DELETE FROM review_decision WHERE translation_version_id IN (SELECT id FROM translation_version WHERE episode_id=?)",id);jdbc.update("DELETE FROM translation_block WHERE episode_id=?",id);jdbc.update("DELETE FROM translation_version WHERE episode_id=?",id);jdbc.update("DELETE FROM episode_assignment WHERE episode_id=?",id);jdbc.update("DELETE FROM source_block WHERE episode_id=?",id);jdbc.update("DELETE FROM episode_source_version WHERE episode_id=?",id);jdbc.update("DELETE FROM domain_audit WHERE episode_id=?",id);jdbc.update("DELETE FROM episode WHERE id=?",id);}for(String id:works){jdbc.update("DELETE FROM work_recommend WHERE work_id=?",id);jdbc.update("DELETE FROM work_episode WHERE work_id=?",id);jdbc.update("DELETE FROM work_cover WHERE work_id=?",id);jdbc.update("DELETE FROM work_genre WHERE work_id=?",id);jdbc.update("DELETE FROM work WHERE id=?",id);}for(var u:users.values()){jdbc.update("DELETE FROM auth_token WHERE account_id=?",u.id());jdbc.update("DELETE FROM auth_audit WHERE account_id=?",u.id());jdbc.update("DELETE FROM demo_account WHERE id=?",u.id());}}
 ResponseEntity<JsonNode> call(HttpMethod method,String path,Object body,String token){var headers=new HttpHeaders();headers.setContentType(MediaType.APPLICATION_JSON);if(token!=null)headers.setBearerAuth(token);return http.exchange(path,method,new HttpEntity<>(body,headers),JsonNode.class);}
 String token(Role role){return users.get(role).token();}
 ResponseEntity<JsonNode> op(HttpMethod method,String path,Object body){return call(method,path,body,token(Role.OPERATOR));}
 ResponseEntity<JsonNode> get(String path){return op(HttpMethod.GET,path,null);}
 Map<String,Object> values(){var v=new LinkedHashMap<String,Object>();v.put("title","  title  ");v.put("author"," author ");v.put("description","intro\nsecond line");v.put("readingDirection","RTL");v.put("genres",List.of("판타지","액션"));return v;}
 String work(){var response=op(HttpMethod.POST,"/api/works",values());assertThat(response.getStatusCode().value()).isEqualTo(201);assertThat(response.getHeaders().getCacheControl()).isEqualTo("no-store");assertThat(fields(response.getBody())).containsExactlyInAnyOrder("id","revision");String id=response.getBody().path("id").textValue();works.add(id);assertThat(response.getBody().path("revision").intValue()).isEqualTo(1);return id;}
 Map<String,Object> update(int revision){var v=values();v.put("expectedRevision",revision);v.put("isPublic",true);v.put("isFeatured",false);v.put("isBanner",false);return v;}
 String episode(){var response=op(HttpMethod.POST,"/api/episodes",Map.of("title","episode"));assertThat(response.getStatusCode().value()).isEqualTo(201);String id=response.getBody().path("id").textValue();episodes.add(id);return id;}
 static List<String> fields(JsonNode node){var result=new ArrayList<String>();node.fieldNames().forEachRemaining(result::add);return result;}
 void error(ResponseEntity<?> response,int status,String code){assertThat(response.getStatusCode().value()).isEqualTo(status);assertThat(response.getHeaders().getCacheControl()).isEqualTo("no-store");String body=response.getBody() instanceof byte[] b?new String(b,java.nio.charset.StandardCharsets.UTF_8):String.valueOf(response.getBody());assertThat(body).contains("\"error\"","\"code\"","\"message\"",code).doesNotContain("Exception","jdbc:","unused-test-hash","SQLState","image_data","SECRET DB detail","PRIVATE DB FAILURE");}
 byte[] png(){return new byte[]{(byte)0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a,1,2};}
 byte[] jpeg(){return new byte[]{(byte)0xff,(byte)0xd8,(byte)0xff,1};}
 byte[] webp(){return new byte[]{'R','I','F','F',4,0,0,0,'W','E','B','P',1};}
 ResponseEntity<byte[]> cover(HttpMethod method,String id,byte[] bytes,String type,String token){var headers=new HttpHeaders();if(type!=null)headers.set("Content-Type",type);if(token!=null)headers.setBearerAuth(token);return http.exchange("/api/works/"+id+"/cover",method,new HttpEntity<>(bytes,headers),byte[].class);}
 void png(String id){assertThat(cover(HttpMethod.PUT,id,png(),"image/png",token(Role.OPERATOR)).getStatusCode().value()).isEqualTo(201);}

 String publicEpisode(String work,int no,int seq){String e=episode();op(HttpMethod.PUT,"/api/episodes/"+e+"/work",Map.of("workId",work,"episodeNo",no));long actor=users.get(Role.OPERATOR).id();jdbc.update("INSERT INTO episode_source_version(episode_id,version_no,created_by,created_at,block_count) VALUES (?,1,?,UTC_TIMESTAMP(6),1)",e,actor);jdbc.update("INSERT INTO source_block(episode_id,version_no,seq,page_no,body) VALUES (?,1,1,1,'PRIVATE_SOURCE')",e);jdbc.update("UPDATE episode SET latest_source_version=1 WHERE id=?",e);var key=new GeneratedKeyHolder();jdbc.update(c->{var ps=c.prepareStatement("INSERT INTO translation_version(episode_id,version_no,source_version_no,status,created_by,created_at,draft_revision) VALUES (?,1,1,'PUBLISHED',?,UTC_TIMESTAMP(6),1)",Statement.RETURN_GENERATED_KEYS);ps.setString(1,e);ps.setLong(2,actor);return ps;},key);long v=key.getKey().longValue();jdbc.update("INSERT INTO translation_block(translation_version_id,episode_id,source_version_no,source_seq,body) VALUES (?,?,1,1,'public text')",v,e);jdbc.update("INSERT INTO publication(episode_id,translation_version_id,source_version_no,published_by,published_at) VALUES (?,?,1,?,?)",e,v,actor,Timestamp.from(Instant.parse("2026-10-09T00:00:00Z").plusSeconds(seq)));jdbc.update("UPDATE episode SET published_translation_version_id=? WHERE id=?",v,e);return e;}
 void makePublic(String id){var body=update(1);assertThat(op(HttpMethod.PUT,"/api/works/"+id,body).getStatusCode().value()).isEqualTo(200);}

 ResponseEntity<JsonNode> pub(String path){return call(HttpMethod.GET,path,null,null);}
 final String voter="a".repeat(32);
 ResponseEntity<JsonNode> vote(String w,boolean add,Object body,String token){return call(HttpMethod.POST,"/api/public/works/"+w+(add?"/recommend":"/unrecommend"),body,token);}
 @Test void idempotencyCancellationNewTimestampAndSummaryCounts(){String w=work();makePublic(w);publicEpisode(w,1,1);var req=Map.of("voterKey",voter);var first=vote(w,true,req,null);assertThat(fields(first.getBody())).containsExactlyInAnyOrder("recommended","recommendCount");assertThat(first.getBody().path("recommended").booleanValue()).isTrue();assertThat(first.getBody().path("recommendCount").longValue()).isEqualTo(1);Timestamp time=jdbc.queryForObject("SELECT created_at FROM work_recommend WHERE work_id=?",Timestamp.class,w);assertThat(vote(w,true,req,null).getBody().path("recommendCount").longValue()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT created_at FROM work_recommend WHERE work_id=?",Timestamp.class,w)).isEqualTo(time);assertThat(vote(w,true,Map.of("voterKey","b".repeat(32)),null).getBody().path("recommendCount").longValue()).isEqualTo(2);for(String route:List.of("/api/public/works/"+w,"/api/public/works")){var response=pub(route).getBody();if(route.endsWith("works"))response=response.path("items").get(0);assertThat(response.path("recommendCount").longValue()).isEqualTo(2);}assertThat(pub("/api/public/home").getBody().path("popular").get(0).path("recommendCount").longValue()).isEqualTo(2);assertThat(vote(w,false,req,null).getBody().path("recommended").booleanValue()).isFalse();assertThat(vote(w,false,req,null).getBody().path("recommendCount").longValue()).isEqualTo(1);doReturn(time.toInstant().plusSeconds(100)).when(clock).instant();assertThat(vote(w,true,req,null).getBody().path("recommendCount").longValue()).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT created_at FROM work_recommend WHERE work_id=? AND voter_key=?",Timestamp.class,w,voter)).isAfter(time);}
 @Test void invalidBodiesKeysAndMediaAre400AndMethods405(){String w=work();makePublic(w);publicEpisode(w,1,1);for(Object body:List.of(Map.of(),Map.of("voterKey","A".repeat(32)),Map.of("voterKey","a".repeat(31)),Map.of("voterKey","a".repeat(33)),Map.of("voterKey",1),Map.of("voterKey",voter,"extra",1),Map.of("voterKey","g".repeat(32))))for(boolean add:List.of(true,false))error(vote(w,add,body,null),400,"INVALID_REQUEST");for(String type:List.of("text/plain","application/x-www-form-urlencoded")){var h=new HttpHeaders();h.setContentType(MediaType.parseMediaType(type));error(http.exchange("/api/public/works/"+w+"/recommend",HttpMethod.POST,new HttpEntity<>("SECRET",h),JsonNode.class),400,"INVALID_REQUEST");}for(HttpMethod method:List.of(HttpMethod.GET,HttpMethod.PUT,HttpMethod.PATCH,HttpMethod.DELETE))for(String end:List.of("recommend","unrecommend"))error(call(method,"/api/public/works/"+w+"/"+end,null,"bad"),405,"METHOD_NOT_ALLOWED");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM work_recommend",Long.class)).isZero();}
 @Test void publicDefinitionAuthIgnoreAndStorageFailureAreSafe(){String w=work(),hidden=work(),none=work();makePublic(w);makePublic(none);String e=publicEpisode(w,1,1);publicEpisode(hidden,1,1);var req=Map.of("voterKey",voter);for(String id:List.of(hidden,none,"999999","abc","01"))for(boolean add:List.of(true,false))error(vote(id,add,req,null),404,"NOT_FOUND");for(Role role:Role.values())assertThat(vote(w,true,req,token(role)).getStatusCode().value()).isEqualTo(200);for(String token:List.of("bad","Bearer broken"))assertThat(vote(w,true,req,token).getStatusCode().value()).isEqualTo(200);jdbc.update("UPDATE auth_token SET expires_at=UTC_TIMESTAMP(6)-INTERVAL 1 DAY WHERE account_id=?",users.get(Role.READER).id());assertThat(vote(w,true,req,token(Role.READER)).getStatusCode().value()).isEqualTo(200);assertThat(op(HttpMethod.POST,"/api/episodes/"+e+"/publication/hold",null).getStatusCode().value()).isEqualTo(200);error(vote(w,false,req,null),404,"NOT_FOUND");assertThat(op(HttpMethod.POST,"/api/episodes/"+e+"/publication/resume",null).getStatusCode().value()).isEqualTo(200);doThrow(new DataAccessResourceFailureException("SECRET")).when(recommendations).count(Long.parseLong(w));error(vote(w,false,req,null),503,"SERVICE_UNAVAILABLE");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM work_recommend WHERE work_id=?",Long.class,w)).isEqualTo(1);}
 @Test void concurrentSameKeyIsOneVote() throws Exception {String w=work();makePublic(w);publicEpisode(w,1,1);var pool=Executors.newFixedThreadPool(4);try{var jobs=new ArrayList<Future<ResponseEntity<JsonNode>>>();for(int i=0;i<4;i++)jobs.add(pool.submit(()->vote(w,true,Map.of("voterKey",voter),null)));for(var job:jobs)assertThat(job.get(10,TimeUnit.SECONDS).getBody().path("recommendCount").longValue()).isEqualTo(1);}finally{pool.shutdownNow();}}
}
